// Life Simulator offline copy. Generated by tools/build-web.mjs: every file of this version is stored on the
// device when it's installed, so the game opens with no internet. A new version replaces the old copy.
const VERSION = "__VERSION__";
const CACHE = "lifesim-" + VERSION;
const FILES = __FILES__;
self.addEventListener("install", (e) => {
    e.waitUntil(caches.open(CACHE).then(async (c) => {
        // in small batches, so a slow phone connection doesn't time out
        for (let i = 0; i < FILES.length; i += 40) await c.addAll(FILES.slice(i, i + 40));
    }).then(() => self.skipWaiting()));
});
self.addEventListener("activate", (e) => {
    e.waitUntil(caches.keys().then((ks) => Promise.all(ks.filter((k) => k.startsWith("lifesim-") && k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener("fetch", (e) => {
    if (e.request.method !== "GET") return;
    e.respondWith(caches.open(CACHE).then(async (c) => {
        const url = new URL(e.request.url);
        const hit = await c.match(e.request, { ignoreSearch: true }) || (url.pathname.endsWith("/") ? await c.match("index.html") : undefined);
        if (hit) return hit;
        try { return await fetch(e.request); }
        catch { return (await c.match("index.html")) || Response.error(); }
    }));
});
